// Extract file info and determine format
const file = $input.first().json;

const formatMap = {
  'vtt': 'WebVTT',
  'srt': 'SubRip',
  'txt': 'Plain Text',
  'json': 'Structured JSON'
};

const format = file.format || file.filename.split('.').pop().toLowerCase();

return [{
  json: {
    ...file,
    format,
    formatName: formatMap[format] || 'Unknown',
    processingStarted: new Date().toISOString()
  }
}];

// Handle success or failure with detailed error info
const inputData = $('Detect Format').first().json;
const result = $json;

// Check if the request failed
const isError = result.error || result.statusCode >= 400 || 
                (result.result && result.result.includes('Error'));

if (isError) {
  const errorMessage = result.error?.message || 
                       result.message || 
                       result.result || 
                       'Unknown error during analysis';

  console.log(`Failed to process ${inputData.filename}: ${errorMessage}`);

  return [{
    json: {
      success: false,
      filename: inputData.filename,
      format: inputData.format,
      error: errorMessage,
      errorDetails: {
        statusCode: result.statusCode,
        attemptedAt: new Date().toISOString()
      }
    }
  }];
}

// Success case
const resultText = result.result || '';
const isComplete = resultText.includes('COMPLETE:') || resultText.includes('COMPLETE');

return [{
  json: {
    success: isComplete,
    filename: inputData.filename,
    format: inputData.format,
    outputPath: inputData.outputPath,
    result: resultText,
    completedAt: new Date().toISOString(),
    processingTime: Date.now() - new Date(inputData.processingStarted).getTime()
  }
}];

